import XCTest
@testable import BrainSyncKit

/// CVEPCode against the Python side's frames (Fixtures/cvep_frames.json, generated by
/// tools/cvep_fixture.py from brainsync.vep.codes.lagged_codes), plus the edge cases.
final class CVEPCodeTests: XCTestCase {
    private struct Fixture: Decodable {
        struct Case: Decodable {
            var name: String
            var stimulus: StimulusSpec
            var cycleFrames: Int
            var frames: Int
            var bright: [String: String]

            enum CodingKeys: String, CodingKey {
                case name, stimulus, frames, bright
                case cycleFrames = "cycle_frames"
            }
        }
        var cases: [Case]
    }

    private func fixture() throws -> Fixture {
        guard let url = Bundle.module.url(forResource: "cvep_frames", withExtension: "json", subdirectory: "Fixtures")
                ?? Bundle.module.url(forResource: "cvep_frames", withExtension: "json") else {
            throw XCTSkip("Fixtures/cvep_frames.json not generated yet")
        }
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    func testEveryFixtureFrameMatchesPython() throws {
        let fixture = try fixture()
        XCTAssertEqual(Set(fixture.cases.map(\.name)), ["cvep_2", "short_fpb2"])
        for c in fixture.cases {
            let code = try CVEPCode(spec: c.stimulus)
            XCTAssertEqual(code.cycleFrames, c.cycleFrames, c.name)
            for (slot, expected) in c.bright {
                XCTAssertEqual(expected.count, c.frames)
                for (n, ch) in expected.enumerated() {
                    let bright = ch == "1"
                    XCTAssertEqual(code.isBright(slot: slot, frame: n), bright, "\(c.name) \(slot) frame \(n)")
                    XCTAssertEqual(code.opacity(slot: slot, frame: n), bright ? c.stimulus.depth : 0)
                }
            }
        }
    }

    func testCvep2IsTheServersCode() throws {
        let c = try XCTUnwrap(try fixture().cases.first { $0.name == "cvep_2" })
        let code = try CVEPCode(spec: c.stimulus)
        XCTAssertEqual(code.bits.count, 63)
        XCTAssertEqual(code.lags, ["s1": 0, "s2": 31])
        XCTAssertEqual(code.cycleFrames, 63)
        // s2 is s1 delayed by 31 frames.
        for n in 0..<200 {
            XCTAssertEqual(code.isBright(slot: "s2", frame: n + 31), code.isBright(slot: "s1", frame: n))
        }
    }

    func testNegativeFramesWrapLikePythonModulo() throws {
        let code = try CVEPCode(bits: "1000", framesPerBit: 1, lags: ["s1": 0, "s2": 1])
        // frame n of s1 is bits[n mod 4]: only n ≡ 0 is bright.
        XCTAssertTrue(code.isBright(slot: "s1", frame: -4))
        XCTAssertFalse(code.isBright(slot: "s1", frame: -1))
        XCTAssertFalse(code.isBright(slot: "s1", frame: -3))
        // s2 on frame 0 shows bits[(0 - 1) mod 4] = bits[3].
        XCTAssertFalse(code.isBright(slot: "s2", frame: 0))
        XCTAssertTrue(code.isBright(slot: "s2", frame: 1))
        XCTAssertTrue(code.isBright(slot: "s2", frame: -3))
        XCTAssertEqual(CVEPCode.mod(-1, 63), 62)
        XCTAssertEqual(CVEPCode.mod(-63, 63), 0)
        XCTAssertEqual(CVEPCode.mod(64, 63), 1)
    }

    func testFramesPerBitHoldsEachBit() throws {
        let code = try CVEPCode(bits: "110", framesPerBit: 2, lags: ["s1": 0, "s2": 3], depth: 0.5)
        XCTAssertEqual(code.cycleFrames, 6)
        let s1 = (0..<12).map { code.isBright(slot: "s1", frame: $0) }
        XCTAssertEqual(s1, [true, true, true, true, false, false, true, true, true, true, false, false])
        // A 3-frame lag lands mid-bit: frame 0 of s2 is cycle frame 3 (bits[1]), frame 1 is frame 4.
        let s2 = (0..<6).map { code.isBright(slot: "s2", frame: $0) }
        XCTAssertEqual(s2, [true, false, false, true, true, true])
        XCTAssertEqual(code.opacity(slot: "s1", frame: 0), 0.5)
        XCTAssertEqual(code.opacity(slot: "s1", frame: 4), 0)
    }

    func testUnknownSlotIsDark() throws {
        let code = try CVEPCode(bits: "111", framesPerBit: 1, lags: ["s1": 0])
        XCTAssertFalse(code.isBright(slot: "s9", frame: 0))
        XCTAssertEqual(code.opacity(slot: "s9", frame: 0), 0)
    }

    func testCycles() throws {
        let code = try CVEPCode(bits: String(repeating: "1", count: 63), framesPerBit: 1, lags: ["s1": 0])
        XCTAssertTrue(code.isCycleStart(frame: 0))
        XCTAssertTrue(code.isCycleStart(frame: 63))
        XCTAssertTrue(code.isCycleStart(frame: 126))
        XCTAssertFalse(code.isCycleStart(frame: 1))
        XCTAssertFalse(code.isCycleStart(frame: 62))
        XCTAssertFalse(code.isCycleStart(frame: -63))
        XCTAssertEqual(code.cycle(ofFrame: 0), 0)
        XCTAssertEqual(code.cycle(ofFrame: 62), 0)
        XCTAssertEqual(code.cycle(ofFrame: 63), 1)
        XCTAssertEqual(code.cycle(ofFrame: 139), 2)
        XCTAssertEqual(code.cycle(ofFrame: -1), -1)
        XCTAssertEqual(code.firstFrame(ofCycle: 2), 126)
    }

    func testFrameIndexRoundsToThePeriodAndNeverGoesNegative() {
        let p = 1.0 / 60
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 0, framePeriod: p), 0)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: p, framePeriod: p), 1)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 10 * p + 0.004, framePeriod: p), 10)  // jitter
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 10 * p - 0.004, framePeriod: p), 10)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 63 * p, framePeriod: p), 63)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 3 * p, framePeriod: p), 3)  // a dropped frame skips, never shifts
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: -0.5, framePeriod: p), 0)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: 1, framePeriod: 0), 0)
        XCTAssertEqual(CVEPCode.frameIndex(elapsed: .nan, framePeriod: p), 0)
    }

    func testBadSpecsAreRefused() {
        XCTAssertThrowsError(try CVEPCode(bits: "", framesPerBit: 1, lags: ["s1": 0])) {
            XCTAssertEqual($0 as? CVEPCode.Problem, .emptyBits)
        }
        XCTAssertThrowsError(try CVEPCode(bits: "10x1", framesPerBit: 1, lags: ["s1": 0]))
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 0, lags: ["s1": 0])) {
            XCTAssertEqual($0 as? CVEPCode.Problem, .framesPerBit(0))
        }
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 1, lags: [:]))
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 1, lags: ["s1": -1])) {
            XCTAssertEqual($0 as? CVEPCode.Problem, .lag(slot: "s1", lag: -1))
        }
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 2, lags: ["s1": 8]))
        XCTAssertNoThrow(try CVEPCode(bits: "1011", framesPerBit: 2, lags: ["s1": 7]))
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 1, lags: ["s1": 0], depth: 0))
        XCTAssertThrowsError(try CVEPCode(bits: "1011", framesPerBit: 1, lags: ["s1": 0], depth: 1.5))
        XCTAssertThrowsError(try CVEPCode(spec: StimulusSpec(paradigm: "freq", bits: "1011", lags: ["s1": 0]))) {
            XCTAssertEqual($0 as? CVEPCode.Problem, .paradigm("freq"))
        }
    }
}
